import { FormatTimePrecisionLocale, FormatTimePrecisionThresholdMap } from './types';

export const FORMAT_TIME_DEFAULT_THRESHOLDS = {
    second: 1,
    minute: 60,
    hour: 3600,
    day: 86400,
    week: 604800,
    month: 2592000,
    year: 31536000
};

function sortMapKeys(thresholds: { [key: string]: number }, a: string, b: string): number {
    return thresholds[a] - thresholds[b];
}

export function formatTimeWithPrecision<T extends FormatTimePrecisionThresholdMap<T>>(timeInSeconds: number, thresholds: T, locale: FormatTimePrecisionLocale<T>, precision: number = 2): string {
    const timeArr = [];
    let precisionCount = 0;
    let time = timeInSeconds;

    const sortMap = sortMapKeys.bind(sortMapKeys, thresholds);
    const mapKeys = Object.keys(thresholds).sort(sortMap).reverse() as [keyof T];

    // if the time is 0 then show the last possible unit only
    if (time === 0) {
        const lastKey = mapKeys[mapKeys.length - 1];
        const lowestUnitDescription = locale[lastKey].plural;
        timeArr.push(lowestUnitDescription.replace('${units}', '0'));
    } else {
        for (const key of mapKeys) {
            if (precisionCount === precision && precision > 0) {
                break;
            }

            const thresholdMin = thresholds[key] as number;

            if (time >= thresholdMin || (timeArr.length > 0 && precision === -1)) {
                const timeDividedByThreshold = time / thresholdMin;

                const units = precision === 1 ? Math.round(timeDividedByThreshold) : Math.floor(timeDividedByThreshold);

                const localeString = units === 1 ? locale[key].singular : locale[key].plural;
                timeArr.push(localeString.replace('${units}', units.toString()));

                // update time for the next loop
                time = time - (units * thresholdMin);
                precisionCount++;
            } else if (precisionCount > 0) {
                precisionCount++;
            }
        }
    }

    return timeArr.join(' ');
}
